    {
      alias: "step_04",
      recipe: {
        type: "native_card",
        title: "Close and review",
        body: "Step 4 — Stand down, document outcomes, and capture improvements."
      }
    }
  ],
  layout: {
    kind: "grid",
    anchor: { alias: "heading" },
    members: ["step_01", "step_02", "step_03", "step_04"],
    columns: 2,
