      kind: "visual",
      source: { alias: "step_01" },
      target: { alias: "step_02" },
      label: "Next"
    },
    {
      kind: "visual",
      source: { alias: "step_02" },
      target: { alias: "step_03" },
      label: "Next"
    },
    {
      kind: "visual",
      source: { alias: "step_03" },
      target: { alias: "step_04" },
      label: "Next"
    }
  ]
});
const cmd = "printf '%s' " + JSON.stringify(plan) + " | /Users/omar/.codex/skills/openpencil/scripts/openpencil-cli.sh board build --fresh-context --target-file '/Users/omar/Documents/Open Pencil/scratch/prompt-to-board-matched-110/target.json' --request-id 'ptb-run:038de657486fe24395a1e7d9673ffc99' --intent 'Build Cooling Center Heat Alert Response process' --plan-file - --json";
const r = await tools.exec_command({
  cmd,
  workdir: "/Users/omar/Documents/Open Pencil",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);

